/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_fb.c
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/cache.h>
#include <nuttx/kmalloc.h>
#include <nuttx/video/fb.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

#include "artinchip_de.h"
#include "artinchip_lvds.h"
#include "artinchip_panel.h"

#define D13X_FB_WIDTH          1024u
#define D13X_FB_HEIGHT         600u
#define D13X_FB_BPP            16u
#define D13X_FB_STRIDE         (D13X_FB_WIDTH * 2u)
#define D13X_FB_FRAME_SIZE     (D13X_FB_STRIDE * D13X_FB_HEIGHT)
#define D13X_FB_BUFFERS        2u
#define D13X_FB_TOTAL_SIZE     (D13X_FB_FRAME_SIZE * D13X_FB_BUFFERS)
#define D13X_CACHE_LINE_SIZE   32u
#define D13X_CACHE_RANGE_LIMIT (64u * 1024u)
#define THEAD_MHCR_DCACHE_EN   (1u << 1)

struct d13x_fb_state_s
{
  bool initialized;
  bool power_on;
  uint8_t *memory;
  uint32_t displayed_yoffset;
  struct fb_area_s update_area;
  bool update_pending;
};

static struct d13x_fb_state_s g_fb;

static void d13x_fb_clean_cache(void)
{
  uint32_t mhcr;

  /* The custom D13x port does not expose NuttX ARCH_DCACHE hooks, while the
   * E907 may inherit an enabled write-back cache from the bootloader.  Use
   * the vendor's numeric CSR and raw dcache.call encoding so ordinary GCC
   * toolchains still make framebuffer writes visible to the DE DMA master.
   */

  __asm__ __volatile__("csrr %0, 0x7c1" : "=r"(mhcr));
  if ((mhcr & THEAD_MHCR_DCACHE_EN) != 0)
    {
      __asm__ __volatile__("fence rw, rw" ::: "memory");
      __asm__ __volatile__(".long 0x0010000b" ::: "memory");
      __asm__ __volatile__("fence rw, rw" ::: "memory");
    }
}

static void d13x_fb_clean_cache_area(const void *address, size_t row_bytes,
                                     size_t stride, size_t row_count)
{
  uintptr_t row;
  uint32_t mhcr;
  size_t index;

  if (row_bytes == 0 || row_count == 0)
    {
      return;
    }

  /* A cache-wide clean is bounded by the cache capacity and is faster than
   * issuing tens of thousands of per-line operations for a large redraw.
   */

  if (row_bytes * row_count >= D13X_CACHE_RANGE_LIMIT)
    {
      d13x_fb_clean_cache();
      return;
    }

  __asm__ __volatile__("csrr %0, 0x7c1" : "=r"(mhcr));
  if ((mhcr & THEAD_MHCR_DCACHE_EN) == 0)
    {
      return;
    }

  __asm__ __volatile__("fence" ::: "memory");
  row = (uintptr_t)address;
  for (index = 0; index < row_count; index++)
    {
      uintptr_t current = row & ~(D13X_CACHE_LINE_SIZE - 1u);
      uintptr_t end = (row + row_bytes + D13X_CACHE_LINE_SIZE - 1u) &
                      ~(D13X_CACHE_LINE_SIZE - 1u);

      while (current < end)
        {
          register uintptr_t cache_address __asm__("a0") = current;

          /* T-Head dcache.cpa cleans one physical cache line. */

          __asm__ __volatile__(".long 0x0295000b" : "+r"(cache_address) ::
                               "memory");
          current += D13X_CACHE_LINE_SIZE;
        }

      row += stride;
    }

  __asm__ __volatile__("fence\n\t"
                       "fence.i\n\t"
                       ".long 0x01a0000b" ::: "memory");
}

static int d13x_fb_getvideoinfo(struct fb_vtable_s *vtable,
                                struct fb_videoinfo_s *vinfo)
{
  (void)vtable;

  if (vinfo == NULL)
    {
      return -EINVAL;
    }

  vinfo->fmt = FB_FMT_RGB16_565;
  vinfo->xres = D13X_FB_WIDTH;
  vinfo->yres = D13X_FB_HEIGHT;
  vinfo->nplanes = 1;
  return OK;
}

static int d13x_fb_getplaneinfo(struct fb_vtable_s *vtable, int planeno,
                                struct fb_planeinfo_s *pinfo)
{
  (void)vtable;

  if (planeno != 0 || pinfo == NULL || !g_fb.initialized)
    {
      return -EINVAL;
    }

  pinfo->fbmem = g_fb.memory;
  pinfo->fblen = D13X_FB_TOTAL_SIZE;
  pinfo->stride = D13X_FB_STRIDE;
  pinfo->display = 0;
  pinfo->bpp = D13X_FB_BPP;
  pinfo->xres_virtual = D13X_FB_WIDTH;
  pinfo->yres_virtual = D13X_FB_HEIGHT * D13X_FB_BUFFERS;
  pinfo->xoffset = 0;
  pinfo->yoffset = 0;
  return OK;
}

#ifdef CONFIG_FB_UPDATE
static int d13x_fb_updatearea(struct fb_vtable_s *vtable,
                              const struct fb_area_s *area)
{
  uint32_t x;
  uint32_t y;
  uint32_t width;
  uint32_t height;
  uintptr_t address;

  (void)vtable;

  if (area == NULL || !g_fb.initialized || area->w == 0 || area->h == 0)
    {
      return -EINVAL;
    }

  x = area->x;
  y = area->y;
  width = area->w;
  height = area->h;
  if (x >= D13X_FB_WIDTH || y >= D13X_FB_HEIGHT * D13X_FB_BUFFERS)
    {
      return -EINVAL;
    }

  if (width > D13X_FB_WIDTH - x)
    {
      width = D13X_FB_WIDTH - x;
    }

  if (height > D13X_FB_HEIGHT * D13X_FB_BUFFERS - y)
    {
      height = D13X_FB_HEIGHT * D13X_FB_BUFFERS - y;
    }

  address = (uintptr_t)g_fb.memory + y * D13X_FB_STRIDE + x * 2u;

  d13x_fb_clean_cache_area((const void *)address, width * 2u,
                           D13X_FB_STRIDE, height);
  g_fb.update_area.x = x;
  g_fb.update_area.y = y % D13X_FB_HEIGHT;
  g_fb.update_area.w = width;
  g_fb.update_area.h = height;
  g_fb.update_pending = true;
  return OK;
}
#endif

static int d13x_fb_pandisplay(struct fb_vtable_s *vtable,
                              struct fb_planeinfo_s *pinfo)
{
  uintptr_t address;

  (void)vtable;

  if (pinfo == NULL || !g_fb.initialized ||
      (pinfo->yoffset != 0 && pinfo->yoffset != D13X_FB_HEIGHT))
    {
      return -EINVAL;
    }

  address = (uintptr_t)g_fb.memory + pinfo->yoffset * D13X_FB_STRIDE;

  /* LVGL uses DIRECT double buffering.  Before drawing a new dirty area it
   * copies the previous frame's dirty areas into the back buffer so both
   * framebuffers remain identical.  FBIO_UPDATE only describes the current
   * dirty area and therefore does not cover those synchronization copies.
   * Cleaning just that area can leave stale cache lines in the back buffer,
   * which appear as old labels and widgets after the subsequent page flip.
   *
   * Clean the complete (finite) data cache immediately before publishing the
   * buffer.  This makes every LVGL write visible to the DE DMA master.  It is
   * also cheaper than walking the entire 1.2 MiB framebuffer line by line.
   */

  d13x_fb_clean_cache();
  d13x_de_set_framebuffer(address);
  g_fb.displayed_yoffset = pinfo->yoffset;
  return OK;
}

#ifdef CONFIG_FB_SYNC
static int d13x_fb_waitforvsync(struct fb_vtable_s *vtable)
{
  uint32_t source_y;
  uint32_t dest_y;
  uint32_t row;
  int ret;

  ret = d13x_de_wait_for_vsync();

  if (g_fb.update_pending)
    {
      source_y = g_fb.displayed_yoffset + g_fb.update_area.y;
      dest_y = (g_fb.displayed_yoffset == 0 ? D13X_FB_HEIGHT : 0) +
               g_fb.update_area.y;

      /* LVGL rendered the merged dirty area into the newly displayed page.
       * Mirror that exact area after the frame boundary so the next DIRECT
       * buffer starts from identical pixels instead of an older UI state.
       */

      for (row = 0; row < g_fb.update_area.h; row++)
        {
          memcpy(g_fb.memory + (dest_y + row) * D13X_FB_STRIDE +
                   g_fb.update_area.x * 2u,
                 g_fb.memory + (source_y + row) * D13X_FB_STRIDE +
                   g_fb.update_area.x * 2u,
                 g_fb.update_area.w * 2u);
        }

      d13x_fb_clean_cache_area(
        g_fb.memory + dest_y * D13X_FB_STRIDE +
          g_fb.update_area.x * 2u,
        g_fb.update_area.w * 2u, D13X_FB_STRIDE, g_fb.update_area.h);
      g_fb.update_pending = false;
    }

  /* Release the pan entry after the frame boundary.  Also release it on a
   * hardware timeout so a missing IRQ cannot permanently stop LVGL refresh.
   */

  fb_remove_paninfo(vtable, FB_NO_OVERLAY);

  return ret;
}
#endif

static int d13x_fb_getpower(struct fb_vtable_s *vtable)
{
  (void)vtable;
  return g_fb.power_on ? 1 : 0;
}

static int d13x_fb_setpower(struct fb_vtable_s *vtable, int power)
{
  (void)vtable;

  if (!g_fb.initialized)
    {
      return -ENODEV;
    }

  if (power > 0 && !g_fb.power_on)
    {
      d13x_lvds_enable();
      d13x_de_enable();
      d13x_panel_enable();
      g_fb.power_on = true;
    }
  else if (power <= 0 && g_fb.power_on)
    {
      d13x_panel_disable();
      d13x_de_disable();
      d13x_lvds_disable();
      g_fb.power_on = false;
    }

  return OK;
}

static struct fb_vtable_s g_fb_vtable =
{
  .getvideoinfo = d13x_fb_getvideoinfo,
  .getplaneinfo = d13x_fb_getplaneinfo,
#ifdef CONFIG_FB_UPDATE
  .updatearea = d13x_fb_updatearea,
#endif
  .pandisplay = d13x_fb_pandisplay,
#ifdef CONFIG_FB_SYNC
  .waitforvsync = d13x_fb_waitforvsync,
#endif
  .getpower = d13x_fb_getpower,
  .setpower = d13x_fb_setpower,
};

int up_fbinitialize(int display)
{
  uint32_t hactive;
  uint32_t vactive;
  uint32_t hfp;
  uint32_t hbp;
  uint32_t hsync;
  uint32_t vfp;
  uint32_t vbp;
  uint32_t vsync;
  uint32_t pixel_clock;
  int ret;

  if (display != 0)
    {
      return -ENODEV;
    }

  if (g_fb.initialized)
    {
      return OK;
    }

  g_fb.memory = kmm_memalign(64, D13X_FB_TOTAL_SIZE);
  if (g_fb.memory == NULL)
    {
      return -ENOMEM;
    }

  memset(g_fb.memory, 0, D13X_FB_TOTAL_SIZE);
  d13x_fb_clean_cache();

  d13x_panel_get_timing(&hactive, &vactive, &hfp, &hbp, &hsync,
                         &vfp, &vbp, &vsync, &pixel_clock);

  ret = d13x_panel_initialize();
  if (ret < 0)
    {
      goto errout;
    }

  ret = d13x_lvds_initialize(pixel_clock);
  if (ret < 0)
    {
      goto errout;
    }

  ret = d13x_de_initialize(hactive, vactive, hfp, hbp, hsync,
                           vfp, vbp, vsync, D13X_FB_STRIDE);
  if (ret < 0)
    {
      goto errout;
    }

  d13x_de_set_framebuffer((uintptr_t)g_fb.memory);
  d13x_lvds_enable();
  d13x_de_enable();
  up_mdelay(20);
  d13x_panel_enable();

  g_fb.power_on = true;
  g_fb.initialized = true;
  return OK;

errout:
  d13x_panel_disable();
  d13x_de_disable();
  d13x_lvds_disable();
#ifdef CONFIG_FB_SYNC
  d13x_de_uninitialize_vsync();
#endif
  kmm_free(g_fb.memory);
  memset(&g_fb, 0, sizeof(g_fb));
  return ret;
}

struct fb_vtable_s *up_fbgetvplane(int display, int vplane)
{
  if (display != 0 || vplane != 0 || !g_fb.initialized)
    {
      return NULL;
    }

  return &g_fb_vtable;
}

void up_fbuninitialize(int display)
{
  if (display != 0 || !g_fb.initialized)
    {
      return;
    }

  d13x_panel_disable();
  d13x_de_disable();
  d13x_lvds_disable();
#ifdef CONFIG_FB_SYNC
  d13x_de_uninitialize_vsync();
#endif
  kmm_free(g_fb.memory);
  memset(&g_fb, 0, sizeof(g_fb));
}

/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_de.c
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/semaphore.h>
#include <nuttx/spinlock.h>

#include <errno.h>

#include "chip.h"
#include "artinchip_de.h"
#include "include/irq.h"

#define BIT(n)                    (1u << (n))

#define DE_CONFIG_UPDATE          0x008u
#define VIDEO_LAYER_CTRL          0x020u
#define UI_LAYER_CTRL             0x0a0u
#define UI_LAYER_SIZE             0x0a4u
#define UI_LAYER_RECT_CTRL        0x0b0u
#define UI_RECT_INPUT_SIZE        0x0c0u
#define UI_RECT_OFFSET            0x0c4u
#define UI_RECT_STRIDE            0x0c8u
#define UI_RECT_ADDR              0x0ccu
#define BLENDING_BG_COLOR         0x100u
#define BLENDING_OUTPUT_SIZE      0x104u
#define UI_LAYER_OFFSET           0x10cu
#define WB_CTRL                   0x170u
#define TIMING_CTRL               0x1d0u
#define TIMING_INIT               0x1d4u
#define TIMING_STATUS             0x1d8u
#define TIMING_LINE_SET           0x1dcu
#define TIMING_ACTIVE_SIZE        0x1e0u
#define TIMING_H_PORCH            0x1e4u
#define TIMING_V_PORCH            0x1e8u
#define TIMING_SYNC_PULSE         0x1ecu
#define TIMING_POLARITY           0x1f0u
#define QOS_UI                    0x88cu
#define QOS_URGENT                0x890u

#define UI_FORMAT_RGB565          0x0eu
#define UI_LAYER_ENABLE           BIT(0)
#define UI_ALPHA_ENABLE           BIT(2)
#define TIMING_ENABLE             BIT(0)
#define DE_SOFT_RESET_ENABLE      BIT(16)

#define CMU_CLK_DE                (D13X_CMU_BASE + 0x08c0u)
#define MOD_RESET_DEASSERT        BIT(13)
#define MOD_BUS_ENABLE            BIT(12)
#define MOD_CLOCK_ENABLE          BIT(8)
#define TIMING_V_BLANK_IRQ        BIT(0)

#ifdef CONFIG_FB_SYNC
static sem_t g_de_vsync_sem;
static bool g_de_vsync_initialized;
static volatile bool g_de_vsync_waiting;

static int d13x_de_interrupt(int irq, void *context, void *arg)
{
  uint32_t status;

  (void)irq;
  (void)context;
  (void)arg;

  status = getreg32(D13X_DE_BASE + TIMING_STATUS);
  putreg32(status, D13X_DE_BASE + TIMING_STATUS);
  if ((status & TIMING_V_BLANK_IRQ) != 0 && g_de_vsync_waiting)
    {
      g_de_vsync_waiting = false;
      nxsem_post(&g_de_vsync_sem);
    }

  return OK;
}
#endif

static inline void de_write(uint32_t offset, uint32_t value)
{
  putreg32(value, D13X_DE_BASE + offset);
}

static inline uint32_t de_size(uint32_t width, uint32_t height)
{
  return ((height & 0x1fffu) << 16) | (width & 0x1fffu);
}

int d13x_de_initialize(uint32_t width, uint32_t height,
                       uint32_t hfp, uint32_t hbp, uint32_t hsync,
                       uint32_t vfp, uint32_t vbp, uint32_t vsync,
                       uint32_t stride)
{
  uint32_t reg;

  if (width == 0 || height == 0 || width > 0x1fff || height > 0x1fff ||
      stride > 0x7fff)
    {
      return -EINVAL;
    }

  /* D13x DE v1.1 runs at 150 MHz from PLL_INT1 / 8. */

  reg = getreg32(CMU_CLK_DE);
  reg &= ~0x3fu;
  reg |= 7u | MOD_RESET_DEASSERT | MOD_BUS_ENABLE | MOD_CLOCK_ENABLE;
  putreg32(reg, CMU_CLK_DE);

  de_write(TIMING_CTRL, 0);
  de_write(VIDEO_LAYER_CTRL, 0);
  de_write(UI_LAYER_CTRL, 0);
  de_write(UI_LAYER_RECT_CTRL, 0);
  de_write(TIMING_INIT, 0);
  de_write(TIMING_STATUS, 0xffffffffu);

#ifdef CONFIG_FB_SYNC
  if (!g_de_vsync_initialized)
    {
      nxsem_init(&g_de_vsync_sem, 0, 0);
      if (irq_attach(D13X_IRQ_DE, d13x_de_interrupt, NULL) < 0)
        {
          nxsem_destroy(&g_de_vsync_sem);
          return -EIO;
        }

      g_de_vsync_initialized = true;
    }
#endif

  de_write(TIMING_ACTIVE_SIZE, de_size(width, height));
  de_write(TIMING_H_PORCH, ((hbp & 0x1fffu) << 16) |
                            (hfp & 0x1fffu));
  de_write(TIMING_V_PORCH, ((vbp & 0x1fffu) << 16) |
                            (vfp & 0x1fffu));
  de_write(TIMING_SYNC_PULSE, ((vsync & 0x7ffu) << 16) |
                               (hsync & 0x7ffu));
  de_write(TIMING_POLARITY, 0);
  de_write(TIMING_LINE_SET, 2u << 16);
#ifdef CONFIG_FB_SYNC
  de_write(TIMING_INIT, TIMING_V_BLANK_IRQ);
#else
  de_write(TIMING_INIT, 0);
#endif

  de_write(BLENDING_BG_COLOR, 0);
  de_write(BLENDING_OUTPUT_SIZE, de_size(width, height));
  de_write(UI_LAYER_SIZE, de_size(width, height));
  de_write(UI_LAYER_OFFSET, 0);
  de_write(UI_RECT_INPUT_SIZE, de_size(width, height));
  de_write(UI_RECT_OFFSET, 0);
  de_write(UI_RECT_STRIDE, stride);

  reg = (0xffu << 24) | (UI_FORMAT_RGB565 << 8) |
        UI_ALPHA_ENABLE | UI_LAYER_ENABLE;
  de_write(UI_LAYER_CTRL, reg);
  de_write(UI_LAYER_RECT_CTRL, BIT(0));

  reg = getreg32(D13X_DE_BASE + WB_CTRL);
  de_write(WB_CTRL, reg | DE_SOFT_RESET_ENABLE);

  de_write(QOS_UI, (0xdu << 28) | (0x60u << 16) |
                   (0xdu << 12) | 0x40u);
  de_write(QOS_URGENT, BIT(15) | BIT(14) | 0x40u);
  de_write(DE_CONFIG_UPDATE, BIT(0));
#ifdef CONFIG_FB_SYNC
  up_enable_irq(D13X_IRQ_DE);
#endif
  return OK;
}

void d13x_de_set_framebuffer(uintptr_t address)
{
  de_write(UI_RECT_ADDR, (uint32_t)address);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

void d13x_de_enable(void)
{
  uint32_t reg = getreg32(D13X_DE_BASE + TIMING_CTRL);
  de_write(TIMING_CTRL, reg | TIMING_ENABLE);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

void d13x_de_disable(void)
{
  uint32_t reg = getreg32(D13X_DE_BASE + TIMING_CTRL);
  de_write(TIMING_CTRL, reg & ~TIMING_ENABLE);
  de_write(DE_CONFIG_UPDATE, BIT(0));
}

#ifdef CONFIG_FB_SYNC
int d13x_de_wait_for_vsync(void)
{
  irqstate_t flags;
  int ret;

  if (!g_de_vsync_initialized)
    {
      return -ENODEV;
    }

  flags = enter_critical_section();
  while (nxsem_trywait(&g_de_vsync_sem) == OK)
    {
    }

  g_de_vsync_waiting = true;
  leave_critical_section(flags);

  ret = nxsem_tickwait_uninterruptible(&g_de_vsync_sem,
                                       MSEC2TICK(100));
  if (ret < 0)
    {
      flags = enter_critical_section();
      g_de_vsync_waiting = false;
      leave_critical_section(flags);
    }

  return ret;
}

void d13x_de_uninitialize_vsync(void)
{
  if (g_de_vsync_initialized)
    {
      up_disable_irq(D13X_IRQ_DE);
      irq_detach(D13X_IRQ_DE);
      nxsem_destroy(&g_de_vsync_sem);
      g_de_vsync_initialized = false;
      g_de_vsync_waiting = false;
    }
}
#endif

